1: import { Component, OnInit } from '@angular/core';
2: import { FormControl, FormGroup, Validators } from '@angular/forms';
3: import { TranslateService } from '@ngx-translate/core';
4: import * as moment from 'moment';
5: import { PopUpManager } from 'src/app/managers/popup_manager';
6: import { NivelFormacion } from 'src/data/models/nivel_formacion';
7: import { EventoService } from 'src/data/services/evento.service';
8: import { ProyectoAcademicoService } from 'src/data/services/proyecto_academico.service';
9: import { SgaMidCalendarioService } from 'src/data/services/sga_mid_calendario.service';
10: 
11: @Component({
12:   selector: 'definicion-cortes',
13:   templateUrl: './definicion-cortes.component.html',
14:   styleUrls: ['./definicion-cortes.component.scss']
15: })
16: export class DefinicionCortesComponent implements OnInit {
17:   dataSource = [];
18:   selectedLevel: FormControl;
19:   selectedPeriod: FormControl;
20:   niveles: NivelFormacion[];
21:   periodos: Object[] = [];
22:   proceso: Object;
23: 
24:   corte1_index = -1;
25:   corte2_index = -1;
26:   examen_index = -1;
27:   habilit_index = -1;
28: 
29:   settingDates: FormGroup;
30: 
31:   constructor(
32:     private proyectoService: ProyectoAcademicoService,
33:     private sgaMidCalendarioService: SgaMidCalendarioService,
34:     private eventoService: EventoService,
35:     private popUpManager: PopUpManager,
36:     private translate: TranslateService
37:   ) {
38:     this.selectedLevel = new FormControl('', Validators.required);
39:     this.selectedPeriod = new FormControl('', Validators.required);
40:   }
41: 
42:   ngOnInit() {
43:     this.settingDates = new FormGroup({
44:       corte1_inicio: new FormControl('', Validators.required),
45:       corte1_fin: new FormControl('', Validators.required),
46:       corte2_inicio: new FormControl('', Validators.required),
47:       corte2_fin: new FormControl('', Validators.required),
48:       examen_inicio: new FormControl('', Validators.required),
49:       examen_fin: new FormControl('', Validators.required),
50:       habilit_inicio: new FormControl('', Validators.required),
51:       habilit_fin: new FormControl('', Validators.required)
52:     });
53:     this.settingDates.disable();
54: 
55:     this.proyectoService.get('nivel_formacion?limit=0').subscribe(
56:       (response: NivelFormacion[]) => {
57:         if (response === null) {
58:           this.popUpManager.showErrorAlert(this.translate.instant('notas.sin_niveles'));//"No se encuentra niveles"
59:         } else {
60:           this.niveles = response.filter(nivel => nivel.NivelFormacionPadreId === null);
61:           if (this.niveles === null) {
62:             this.popUpManager.showErrorAlert(this.translate.instant('notas.sin_nivel_especifico'));//"No se encuentran los niveles especificados"
63:           }
64:         }
65:       },
66:       () => {
67:         this.popUpManager.showErrorToast(this.translate.instant('ERROR.general'));
68:       }
69:     );
70:   }
71: 
72:   onSelectLevel(): void {
73:     this.settingDates.reset();
74:     this.settingDates.disable();
75:     if (this.selectedLevel.value !== '') {
76:       this.sgaMidCalendarioService.get('calendario-academico?limit=0').subscribe(
77:         (response: any) => {
78:           if (response !== null && (response.Status == '404' || response.Status == '400')) {
79:             this.popUpManager.showErrorAlert(this.translate.instant('calendario.sin_calendarios'));
80:           } else {
81:             this.periodos = response.Data.filter(periodo => periodo.Nivel === this.selectedLevel.value && periodo.Activo === true);
82:             if (this.periodos === null) {
83:               this.popUpManager.showErrorAlert(this.translate.instant('notas.sin_calendario_nivel'));//"no hay calendarios para este nivel o no se encuentran activos"
84:             }
85:             this.selectedPeriod.setValue('');
86:           }
87:         },
88:         () => {
89:           this.popUpManager.showErrorToast(this.translate.instant('ERROR.general'));
90:         }
91:       );
92:     }
93:   }
94: 
95:   onSelectPeriod(): void {
96:     this.settingDates.reset();
97:     this.settingDates.disable();
98:     if (this.selectedPeriod.value !== '') {
99:       this.proceso = undefined;
100:       this.sgaMidCalendarioService.get('calendario-academico/' + this.selectedPeriod.value).subscribe(
101:         (response: any) => {
102:           if (response === null || !response.Success) {
103:             this.popUpManager.showErrorAlert(this.translate.instant('notas.sin_calendario_periodo'));//"No se encuentra calendario para periodo"
104:           } else {
105:             this.proceso = response.Data[0].proceso != null ? response.Data[0].proceso.filter(proceso => this.existe(proceso.Proceso, ["calificaciones"]))[0] : undefined;
106:             if (this.proceso === undefined) {
107:               this.popUpManager.showErrorAlert(this.translate.instant('notas.no_proceso_calificaciones'));//"No hay proceso de calificaciones"
108:             } else {
109:               this.organizeData();
110:             }
111:           }
112:         },
113:         () => {
114:           this.popUpManager.showErrorToast(this.translate.instant('ERROR.general'));
115:         }
116:       );
117:     }
118:   }
119: 
120:   organizeData(): void {
121:     this.corte1_index = -1;
122:     this.corte2_index = -1;
123:     this.examen_index = -1;
124:     this.habilit_index = -1;
125: 
126:     this.proceso["Actividades"].forEach((element, index) => {
127:       if (this.existe(element.Nombre, ["primer"])) {
128:         this.corte1_index = index;
129:       }
130:       if (this.existe(element.Nombre, ["segundo"])) {
131:         this.corte2_index = index;
132:       }
133:       if (this.existe(element.Nombre, ["ultimo", "examen"])) {
134:         this.examen_index = index;
135:       }
136:       if (this.existe(element.Nombre, ["habilitacion", "habilitaciones"])) {
137:         this.habilit_index = index;
138:       }
139:     });
140: 
141:     if (this.corte1_index === -1) {
142:       this.popUpManager.showErrorAlert(this.translate.instant('notas.sin_corte1'));
143:     } else if (this.corte2_index === -1) {
144:       this.popUpManager.showErrorAlert(this.translate.instant('notas.sin_corte2'));
145:     } else if (this.examen_index === -1) {
146:       this.popUpManager.showErrorAlert(this.translate.instant('notas.sin_examen'));
147:     } else if (this.habilit_index === -1) {
148:       this.popUpManager.showErrorAlert(this.translate.instant('notas.sin_habilit'));
149:     } else {
150:       this.settingDates.patchValue({
151:         corte1_inicio: moment(this.proceso["Actividades"][this.corte1_index].FechaInicio, "YYYY-MM-DDTHH:mm:ss").toDate(),
152:         corte1_fin: moment(this.proceso["Actividades"][this.corte1_index].FechaFin, "YYYY-MM-DDTHH:mm:ss").toDate(),
153:         corte2_inicio: moment(this.proceso["Actividades"][this.corte2_index].FechaInicio, "YYYY-MM-DDTHH:mm:ss").toDate(),
154:         corte2_fin: moment(this.proceso["Actividades"][this.corte2_index].FechaFin, "YYYY-MM-DDTHH:mm:ss").toDate(),
155:         examen_inicio: moment(this.proceso["Actividades"][this.examen_index].FechaInicio, "YYYY-MM-DDTHH:mm:ss").toDate(),
156:         examen_fin: moment(this.proceso["Actividades"][this.examen_index].FechaFin, "YYYY-MM-DDTHH:mm:ss").toDate(),
157:         habilit_inicio: moment(this.proceso["Actividades"][this.habilit_index].FechaInicio, "YYYY-MM-DDTHH:mm:ss").toDate(),
158:         habilit_fin: moment(this.proceso["Actividades"][this.habilit_index].FechaFin, "YYYY-MM-DDTHH:mm:ss").toDate(),
159:       });
160:       this.settingDates.enable();
161:     }
162:   }
163: 
164:   onSubmit(): void {
165:     if (this.settingDates.valid) {
166:       this.proceso["Actividades"][this.corte1_index].FechaInicio = moment(this.settingDates.get("corte1_inicio").value).format('YYYY-MM-DDTHH:mm:ss[Z]');
167:       this.proceso["Actividades"][this.corte1_index].FechaFin = moment(this.settingDates.get("corte1_fin").value).format('YYYY-MM-DDTHH:mm:ss[Z]');
168:       this.proceso["Actividades"][this.corte2_index].FechaInicio = moment(this.settingDates.get("corte2_inicio").value).format('YYYY-MM-DDTHH:mm:ss[Z]');
169:       this.proceso["Actividades"][this.corte2_index].FechaFin = moment(this.settingDates.get("corte2_fin").value).format('YYYY-MM-DDTHH:mm:ss[Z]');
170:       this.proceso["Actividades"][this.examen_index].FechaInicio = moment(this.settingDates.get("examen_inicio").value).format('YYYY-MM-DDTHH:mm:ss[Z]');
171:       this.proceso["Actividades"][this.examen_index].FechaFin = moment(this.settingDates.get("examen_fin").value).format('YYYY-MM-DDTHH:mm:ss[Z]');
172:       this.proceso["Actividades"][this.habilit_index].FechaInicio = moment(this.settingDates.get("habilit_inicio").value).format('YYYY-MM-DDTHH:mm:ss[Z]');
173:       this.proceso["Actividades"][this.habilit_index].FechaFin = moment(this.settingDates.get("habilit_fin").value).format('YYYY-MM-DDTHH:mm:ss[Z]');
174: 
175:       this.proceso["Actividades"].forEach(actividad => {
176:         this.eventoService.get('calendario_evento/' + actividad.actividadId).subscribe(
177:           response => {
178:             if (response === null) {
179:               this.popUpManager.showErrorAlert(this.translate.instant('notas.sin_actividad'));//"No se encuentra la actividad");
180:             } else {
181:               const actividadEditada = response;
182:               actividadEditada.FechaInicio = actividad.FechaInicio;
183:               actividadEditada.FechaFin = actividad.FechaFin;
184:               this.eventoService.put('calendario_evento', actividadEditada).subscribe(
185:                 () => {
186:                   this.popUpManager.showSuccessAlert(this.translate.instant('notas.ajuste_exitoso'));//"Ajuste de fechas exitoso"
187:                 },
188:                 () => {
189:                   this.popUpManager.showErrorToast(this.translate.instant('calendario.error_registro_actividad'));
190:                 },
191:               );
192:             }
193:           },
194:           () => {
195:             this.popUpManager.showErrorToast(this.translate.instant('ERROR.general'));
196:           },
197:         );
198:       })
199:     }
200:   }
