202:   cleanAll(): void {
203:     this.selectedLevel.reset();
204:     this.selectedLevel.setErrors(null);
205:     this.selectedPeriod.reset();
206:     this.selectedPeriod.setErrors(null);
207:     this.settingDates.reset();
